bool ProfileHighLevel::FindProfile(const char *name, Id &id)
{
	if (!name)
		return false;

	ProfileFastCS::Lock lock(cs);
	for (ProfileId *cur = ProfileId::GetFirst(); cur; cur = cur->GetNext())
		if (!strcmp(name, cur->GetName()))
		{
			id.m_idPtr = cur;
			return true;
		}
	id.m_idPtr = NULL;
	return false;
}

